-- Phase 1: fresh cv v3-locked-172 + Fields/Subjects DB home + 172 topics (inactive)
ALTER TABLE achievements ADD COLUMN IF NOT EXISTS field text;
ALTER TABLE achievements ADD COLUMN IF NOT EXISTS subject text;
SELECT (SELECT count(*) FROM achievements WHERE curriculum_version_id='a7c1f2e0-9b34-4d55-8e21-0c4f6a9b1d72') AS new_topics, (SELECT count(DISTINCT field) FROM achievements WHERE curriculum_version_id='a7c1f2e0-9b34-4d55-8e21-0c4f6a9b1d72') AS fields, (SELECT count(DISTINCT subject) FROM achievements WHERE curriculum_version_id='a7c1f2e0-9b34-4d55-8e21-0c4f6a9b1d72') AS subjects;
COMMIT;